import{_ as s,a0 as p,w as a,s as l,ao as u,I as r,x as e,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse(`{"title":"開源是冷酷無情的：谷歌Chris DiBona訪談 | LCTT x X-CMD","titleTemplate":false,"description":"開源是冷酷無情的：谷歌Chris DiBona訪談 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源是冷酷無情的：谷歌Chris DiBona訪談 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源是冷酷無情的：谷歌Chris DiBona訪談 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Open source is brutal- an interview with Google's Chris DiBona","title":"開源是冷酷無情的：谷歌Chris DiBona訪談","tag":"201310","desc":""},"relativePath":"201310/Open source is brutal- an interview with Google's Chris DiBona.md","filePath":"[post].md"}`),d={name:"201310/Open source is brutal- an interview with Google's Chris DiBona.md"};function m(C,i,h,f,T,x){const t=p("Link");return a(),l("div",null,[i[11]||(i[11]=u('<h1 id="開源是冷酷無情的-谷歌chris-dibona訪談" tabindex="-1">開源是冷酷無情的：谷歌Chris DiBona訪談 <a class="header-anchor" href="#開源是冷酷無情的-谷歌chris-dibona訪談" aria-label="Permalink to “開源是冷酷無情的：谷歌Chris DiBona訪談”">​</a></h1><p><img src="https://opensource.com/sites/default/files/imagecache/image-full-size/images/law/LAW_imaginationcrucial.png" alt="img"></p><p>Chris DiBona是谷歌開源總監。他也是開源界傑出的領軍人物之一，這還要追溯到他的大學時期，那時他對Linux可謂一見鍾情。</p><p>在今年的 “一切皆開源” 大會上，Christ將會提供谷歌目前的開源軟件活動的最新消息以及對過去的回顧，還有Android的起源和現況。</p><p>我遇到了Christ，我們討論了他最喜愛的Linux發行版、開源的無情法則以及他對谷歌作為業界領袖應有的責任的看法。</p><p>以下是訪談詳情。</p><p>###問：對於你加入谷歌並且在開源部門展開工作，有那些方面是我們所不知道的？</p><p>答： 第一次使用Linux是在上學的時候，由於當時選修了操作系統課程，因此，我需要寫一些有關客户端/服務器的東西。出乎意料的是，那時候Sun工作站實驗室很熱鬧，因為公開探討問題的風氣使然，編碼味十足，使用的終端跑得相當慢。我在想，瓶頸在哪，不妨就用一直都擺放在家裏的一台486-16上試試這個linux到底怎麼樣。這是我有史以來最棒的一次決定！從此我喜歡上了linux系統。linux太棒了，運行很快，與其他unix系統相比，功能齊全。OS這門課程，我也得了A。</p><p>###問：下面這個問題的危險程度跟詢問你最喜歡的球隊一樣，你最喜歡哪個linux發行版？</p><p>答： 哈！如果輕率地回答，那麼是Android，因為Android是基於linux內核的，而我對它的使用頻度遠遠超過其他一些東西。儘管通常情況下討論Android時，多數人都不把它當做一個發行版。我現在正在一個Ubuntu/Debian衍生版本上運行的Chrome瀏覽器中回覆你這個問題的回答，我在谷歌計算引擎上運行的是Debian，在家裏則經常用Fedora。出席公共場合的時候，大多數情況下我攜帶Chromebook，感覺用它最安全。那麼最喜歡的就是Android。</p><p>###問：2004年加入谷歌之前，你在開源和linux領域投入了許多精力，是什麼原因促使你加入谷歌?</p><p>答： 從事了一小段時間諮詢方面的工作以後，當我決定開始全職工作，谷歌的offer對我來説最富有吸引力。 成為谷歌開源人、白手起家開始創業的想法深深地吸引着我。我感覺無論過去還是現在，谷歌始終在計算機科學領域做着有趣的事情，而且以它獨有的方式吸引着我，這些是其他offer所不具備的。</p><p>###問：你不但指導各種項目的開發，而且也參與了Google Ventures，為該項目的啓動注資，那麼你在一個項目中想要尋求什麼，是什麼讓你説出“是的，我就是想幫你”這樣的話 ?</p><p>答： 呃，坦白説，我希望它能夠做的有趣。對於Google Ventures，我並不需要過多的深入其中，而開源問題就不同了，有趣而且參與者眾多。</p><p>###問：多年前的一次採訪中你曾經説過：“谷歌與開源社區同行。贊助意味着責任，這是相當嚴肅的一件事情。”谷歌是否打算避免在自己參與的社區中擔責，二者之間存在必然聯繫嗎？</p><p>答： 我想是這樣的。我希望谷歌工程師和非谷歌開源界的工程師都能把對方看做計算機科學領域的同儕。我們得意識到，對開源項目的廣泛資助預示着責任，比如項目控制，大家都知道，事情就應該這麼做，即使真的沒什麼聯繫。</p><p>###問：你曾經稱開源是“無情”的,具體是什麼意思?</p><p>答： 呃，我還以為你會問為什麼開源可以行得通，什麼時候會考慮開源軟件工程管理在業內是如何運作，但是你沒有。分散的、不同特性的團隊在公司裏相當難運作，但是在開源領域，可以創作出世界級非常優秀的軟件。為什麼會這樣？</p><p>因為我認為，在開源項目中，你可以選擇只和富有成效的人一起工作而忽視其他人。這種行為被理解為非常尖刻和排斥性的。然而實情原本就如此：無情並別排斥那些無所貢獻的人。</p><p>然而這就是為什麼項目克隆如此重要。無論出於什麼原因，如果一個人被排斥在一個項目之外，那麼他們可以克隆該項目然後使該項目朝着一個新方向發展。假如他們的想法及實現優於先前被拒絕加入的項目，那麼，好吧，這次克隆成為新的現實，而那些拒絕別的開發者加入的傢伙現在則嚐到了被拒絕的滋味。</p><p>所以，我想説，開源世界是一個適者生存、優勝劣汰的殘酷機制，但是這樣卻能生產出高質量的軟件產品。誠然，對新手來説比較難上手……</p><p>###問：14年前，你在O&#39;Reilly出版過一本有關開源的書。這些年開源領域是否了發生大的變化？你認為將來開源模式會取代專有模式嗎？</p><p>答： 開源界確實發生了一些變化，非常顯著的一點就是公司裏從事開源工作的人數的增長。而且我還覺察到學術界參與開源的人數有所下降，我把它歸咎於技術轉讓專利申請，對代碼許可權確實是個障礙。類似的，一些來自大學和公司的開源代碼不足以稱之為開源，因為圍繞着專利要應付相當多的問題。我很想説要不是有專利授權許可，我們應該都持懷疑態度，但是在這個時候説這樣的話就有一點走極端了。</p><hr>',24)),r("p",null,[i[1]||(i[1]=e("via: ",-1)),n(t,{href:"https://opensource.com/business/13/10/interview-chris-dibona"},{default:o(()=>[...i[0]||(i[0]=[e("https://opensource.com/business/13/10/interview-chris-dibona",-1)])]),_:1})]),r("p",null,[i[4]||(i[4]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[2]||(i[2]=[e("LCTT",-1)])]),_:1}),i[5]||(i[5]=e(" 原創翻譯，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...i[3]||(i[3]=[e("Linux中國",-1)])]),_:1}),i[6]||(i[6]=e(" 榮譽推出",-1))]),r("p",null,[i[9]||(i[9]=e("譯者：",-1)),n(t,{href:"https://github.com/l3b2w1"},{default:o(()=>[...i[7]||(i[7]=[e("l3b2w1",-1)])]),_:1}),i[10]||(i[10]=e(" 校對：",-1)),n(t,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...i[8]||(i[8]=[e("Caroline",-1)])]),_:1})])])}const _=s(d,[["render",m]]);export{D as __pageData,_ as default};
